import json, random, subprocess, sys, os, ipaddress
sys.path.insert(0, '/workspace/tmp/t')
import ref

WORK = '/workspace/tmp/t/work'
os.makedirs(WORK, exist_ok=True)
CAND = ['python3', '/workspace/submission/ipv6_replay.py']

src = open('/workspace/tmp/t/fuzz.py').read().split('def run(')[0]
ns = {}; exec(src, ns)
gen_manifest = ns['gen_manifest']; rand_addr = ns['rand_addr']

def mutate(rng, plan, m):
    p = rng.choice(plan['probes'])
    base = {'probe_id': p['id'], 'received_ms': p['sent_ms'] + rng.randint(0, max(0, m['timeout_ms']-1)),
            'target': p['target'], 'source': p['target'], 'type': 129, 'code': 0}
    mode = rng.randrange(14)
    if mode == 0:
        return (b'\xef\xbb\xbf' + json.dumps(base).encode())
    if mode == 1:
        s = json.dumps(base)
        i = rng.randrange(len(s))
        return s[:i].encode() + bytes([rng.choice([0xff, 0x80, 0xc3, 0xe2])]) + s[i:].encode()
    if mode == 2:
        return json.dumps(base)[:-1] + ',NaN}'
    if mode == 3:
        return json.dumps(base)[:-1] + ',"received_ms":1e400}'
    if mode == 4:
        d = dict(base); d['extra'] = 1
        return json.dumps(d).encode()
    if mode == 5:
        d = dict(base); del d[rng.choice(list(d))]
        return json.dumps(d).encode()
    if mode == 6:
        d = dict(base); d['received_ms'] = rng.choice([True, False, 1.0, None, '5', [1], {'a': 1}])
        return json.dumps(d).encode()
    if mode == 7:
        d = dict(base); d['type'] = rng.choice([True, 1.5, '129', None])
        return json.dumps(d).encode()
    if mode == 8:
        d = dict(base); d['probe_id'] = rng.choice(['', 'x' * 201, 'x' * 200, 5, None])
        return json.dumps(d).encode()
    if mode == 9:
        d = dict(base); a = rng.choice(['2001:db8::1%eth0', ' 2001:db8::1', '2001:db8::1 ', '2001:db9::1',
                                        '1.2.3.4', '2001:db8::/64', '::1', '2001:DB8::1%0', 'ff02::1',
                                        '2001:db8::1/64', '0:0:0:0:0:0:0:0', '2001:db8:0:0:0:0:0:0'])
        d['source' if rng.random() < 0.5 else 'target'] = a
        return json.dumps(d).encode()
    if mode == 10:
        d = dict(base); d['probe_id'] = 'nope/' + p['id']
        return json.dumps(d).encode()
    if mode == 11:
        d = dict(base); d['target'] = rand_addr(rng)
        return json.dumps(d).encode()
    if mode == 12:
        d = dict(base); d['received_ms'] = rng.choice([p['sent_ms'] - 1, p['deadline_ms'], p['deadline_ms'] - 1, p['sent_ms'], 10**20, -5])
        return json.dumps(d).encode()
    d = dict(base); d['type'], d['code'] = rng.choice([(129, 1), (129, -1), (1, 7), (1, -1), (1, 6), (0, 0), (3, 255), (129, 0)])
    return json.dumps(d).encode()

def dup_key_line(rng, plan):
    p = rng.choice(plan['probes'])
    body = json.dumps({'probe_id': p['id'], 'received_ms': p['sent_ms'], 'target': p['target'],
                       'source': p['target'], 'type': 129, 'code': 0})[1:-1]
    return ('{' + body + ',"code":0}').encode()

bad = 0
count = int(sys.argv[1]) if len(sys.argv) > 1 else 50
for it in range(count):
    rng = random.Random(90000 + it)
    m = gen_manifest(rng)
    plan = ref.ref_plan(m)[0]
    rows = []
    for _ in range(rng.randint(0, 40)):
        r = rng.random()
        if r < 0.45:
            rows.append(mutate(rng, plan, m))
        elif r < 0.55:
            rows.append(dup_key_line(rng, plan))
        elif r < 0.75:
            rows.append(b'')
        elif r < 0.8:
            rows.append(b'  \t ')
        else:
            rows.append(json.dumps({'probe_id': rng.choice(plan['probes'])['id'],
                                    'received_ms': rng.randint(0, 10**12),
                                    'target': rand_addr(rng), 'source': rand_addr(rng),
                                    'type': rng.choice([129, 1]), 'code': rng.randint(0, 6)}).encode())
    rng.shuffle(rows)
    mp = os.path.join(WORK, 'm2.json'); rp = os.path.join(WORK, 'r2.jsonl')
    open(mp, 'w').write(json.dumps(m))
    with open(rp, 'wb') as f:
        for row in rows:
            f.write(row + (b'\r\n' if rng.random() < 0.3 else b'\n'))
        if rows and rng.random() < 0.5:
            pass
    g = subprocess.run(CAND + ['replay', mp, rp], capture_output=True, timeout=120)
    if g.returncode != 0:
        print('FAIL', it, g.returncode, g.stderr[:200]); bad += 1; continue
    exp = ref.ref_replay(m, rows)
    got = json.loads(g.stdout)
    if got != exp:
        print('MISMATCH', it); bad += 1
        for k in exp:
            if got.get(k) != exp[k]:
                print(' key', k)
                if k == 'diagnostics':
                    a = got[k]; b = exp[k]
                    print('  got', a[:20]); print('  exp', b[:20])
                    for i, (x, y) in enumerate(zip(a, b)):
                        if x != y: print('  first diff line', x, y); break
                else:
                    print('  got', json.dumps(got.get(k))[:400]); print('  exp', json.dumps(exp[k])[:400])
        if bad > 2: break
print('done bad=', bad)
